// Общие шаги для тикетов, принятых 19.10.2026 (онбординг после регистрации: #ba6e9b8d точки прогресса, #f688d2b0 порядок экранов,
// #6370c87e «מיקום» у нового аккаунта). Не spec (нет .e2e) — wdio его не запускает.
// Правило iOS: ничего не нажимать в верхних 140 pt (кнопка «חזרה» y=62 открывает Центр уведомлений) — safeClick проверяет это.
import { $, $$, driver } from '@wdio/globals';
import { byText, byTextContains, allByText } from '../../helpers/ui.ts';
import { shown } from './app-0710.ts';

/** Верхняя зона, где на iOS нажимать нельзя (pt). */
export const TOP_NO_TAP = 140;
export const MANUAL_WAIT = 900000;   // 15 минут на ручной шаг

type El = WebdriverIO.Element;

/** Нажать элемент, только если он не в верхних 140 pt (iOS). Координатных тапов нет — click по элементу. */
export async function safeClick(el: El, what: string) {
  await el.waitForDisplayed({ timeout: 20000 });
  const { y } = await el.getLocation();
  if (driver.isIOS && y < TOP_NO_TAP) throw new Error(`«${what}» в верхних ${TOP_NO_TAP} pt (y=${y}) — не нажимаем (правило iOS)`);
  await el.click();
}

/** Первый видимый элемент с точным текстом ниже верхней зоны. */
export async function visibleTextBelowTop(text: string): Promise<El | null> {
  for (const el of await allByText(text)) {
    if (!(await el.isDisplayed().catch(() => false))) continue;
    const { y } = await el.getLocation();
    if (!driver.isIOS || y >= TOP_NO_TAP) return el as unknown as El;
  }
  return null;
}

export async function tapTextSafe(text: string) {
  let el: El | null = null;
  await driver.waitUntil(async () => (el = await visibleTextBelowTop(text)) !== null,
    { timeout: 20000, interval: 500, timeoutMsg: `нет «${text}» ниже ${TOP_NO_TAP} pt` });
  await safeClick(el as unknown as El, text);
}

// ---------- Точки прогресса ----------
export type Dot = { x: number; y: number; width: number; height: number; visible: boolean };

/** Все элементы 'progress-dot' (accessibility name) без прокрутки, слева направо. */
export async function readProgressDots(): Promise<Dot[]> {
  const els = driver.isAndroid
    ? await $$('android=new UiSelector().description("progress-dot")').getElements()
    : await $$('-ios predicate string:name == "progress-dot" OR label == "progress-dot"').getElements();
  const out: Dot[] = [];
  for (const el of els) {
    const { x, y } = await el.getLocation();
    const { width, height } = (await el.getSize()) as { width: number; height: number };
    const visible = driver.isIOS
      ? String(await el.getAttribute('visible').catch(() => '')) === 'true'
      : await el.isDisplayed().catch(() => false);
    out.push({ x, y, width, height, visible });
  }
  return out.sort((a, b) => a.x - b.x);
}

/** Номер активной точки СПРАВА (1 = крайняя справа, RTL). Активная — единственная широкая (32 pt против 8). -1 — не определить. */
export function activeFromRight(d: Dot[]): number {
  if (d.length < 2) return -1;
  const maxW = Math.max(...d.map((p) => p.width));
  const wide = d.filter((p) => p.width === maxW);
  if (wide.length !== 1 || maxW - Math.min(...d.map((p) => p.width)) < 2) return -1;
  return d.length - d.indexOf(wide[0]);
}

/** Все точки видимы и целиком в пределах экрана (без прокрутки). */
export async function dotsOnScreen(d: Dot[]): Promise<boolean> {
  const { height } = await driver.getWindowSize();
  return d.length > 0 && d.every((p) => p.visible && p.y >= 0 && p.y + p.height <= height);
}

// ---------- Экран «מיקום» ----------
export const LOC_SHARE = 'שתף את מיקומך הנוכחי';   // не нажимать — системный запрос геопозиции
export const LOC_PICK = 'בחר מיקום';
export const LOC_FIELD = 'שם המיקום';
export const LOC_CHOSEN = 'העיר נבחרה';

/** Поле «שם המיקום» (подпись, placeholder или accessibility name). */
export function locationField() {
  return driver.isAndroid
    ? $(`//android.widget.EditText[contains(@text,"${LOC_FIELD}") or contains(@content-desc,"${LOC_FIELD}") or contains(@hint,"${LOC_FIELD}")]`)
    : $(`-ios predicate string:type == "XCUIElementTypeTextField" AND (name == "${LOC_FIELD}" OR label CONTAINS "${LOC_FIELD}" OR placeholderValue CONTAINS "${LOC_FIELD}")`);
}

/** Есть ли на экране поле/подпись «שם המיקום». */
export async function locationFieldShown(): Promise<boolean> {
  if (await (await locationField()).isDisplayed().catch(() => false)) return true;
  if (await shown(byTextContains(LOC_FIELD))) return true;
  if (driver.isIOS) {
    const ph = await $(`-ios predicate string:placeholderValue CONTAINS "${LOC_FIELD}"`);
    if (await ph.isDisplayed().catch(() => false)) return true;
  }
  return false;
}

/** «בחר מיקום» → поле «שם המיקום» → ввести город → подсказка «<город>, …, ישראל». Возвращает текст подсказки. */
export async function pickCity(city: string): Promise<string> {
  await tapTextSafe(LOC_PICK);
  let field = (await locationField()) as unknown as El;
  if (!(await field.waitForDisplayed({ timeout: 15000 }).then(() => true).catch(() => false))) {
    // Запасной путь: единственное текстовое поле экрана.
    field = (await (driver.isAndroid
      ? $('android=new UiSelector().className("android.widget.EditText")')
      : $('-ios class chain:**/XCUIElementTypeTextField'))) as unknown as El;
  }
  await safeClick(field, LOC_FIELD);
  await field.setValue(city);
  const re = `^${city}, .*ישראל$`;
  let hint: El | null = null;
  await driver.waitUntil(async () => {
    const all = driver.isAndroid
      ? await $$(`android=new UiSelector().textMatches("${re}")`).getElements()
      : await $$(`-ios predicate string:label MATCHES "${re}" OR value MATCHES "${re}"`).getElements();
    for (const el of all) {
      if (!(await el.isDisplayed().catch(() => false))) continue;
      const { y } = await el.getLocation();
      if (!driver.isIOS || y >= TOP_NO_TAP) { hint = el as unknown as El; return true; }
    }
    return false;
  }, { timeout: 20000, interval: 700, timeoutMsg: `нет подсказки «${city}, …, ישראל»` });
  const h = hint as unknown as El;
  const label = String((await h.getAttribute(driver.isAndroid ? 'text' : 'label').catch(() => '')) ?? '');
  await safeClick(h, label || city);
  return label;
}

// ---------- Экраны онбординга ----------
/** Заголовок шага: точный текст; «מה מניע אותך» — по подстроке (может быть с «?»). TODO калибровка на первом прогоне. */
export function stepTitle(title: string, contains = false) {
  return contains ? byTextContains(title) : byText(title);
}

/** Кнопка «המשך» ниже верхней зоны и её доступность. null — кнопки нет. */
export async function continueEnabled(): Promise<boolean | null> {
  const el = await visibleTextBelowTop('המשך');
  if (!el) {
    const lbl = await $('~המשך');
    if (!(await lbl.isExisting().catch(() => false))) return null;
    return lbl.isEnabled().catch(() => null);
  }
  return el.isEnabled().catch(() => null);
}

/** Ползунок «רמת ההתחזקות» (Adjustable) — есть ли на экране. Только для лога (тип элемента не калиброван). */
export async function sliderShown(): Promise<boolean> {
  const el = driver.isAndroid
    ? await $('android=new UiSelector().className("android.widget.SeekBar")')
    : await $('-ios predicate string:type == "XCUIElementTypeSlider"');
  return el.isDisplayed().catch(() => false);
}
